/** Hands line art, drawn on with anime.js's svg.createDrawable */
const LoveIllustration: React.FC<Props> = ({ size = 36, color = 'currentColor', active = true }) => {
  const pathRef = useRef<SVGPathElement>(null);

  useEffect(() => {
    if (!active) return;
    const path = pathRef.current;
    if (!path) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const [drawable] = svg.createDrawable(path);
    const animation = animate(drawable, {
      draw: ['0 0', '0 1'],
      duration: 1800,
      ease: 'inOutQuad',
    });

    return () => {
      animation.pause();
    };
  }, [active]);

  return (
    <svg width={size} height={size} viewBox="0 0 515 484" fill="none">
      <g transform="translate(0,484) scale(0.1,-0.1)">
        <path
          ref={pathRef}
          d={PATH_D}
          fill="none"
          stroke={color}
          strokeWidth={18}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>
    </svg>
  );
};

export default LoveIllustration;
